(function () {
  'use strict';
  var D = window.DCW, h = D.h, C = D.C, fmtN = D.fmtN, SANS = D.SANS, MONO = D.MONO;

  /* ---- pure functions ---- */
  var IJ = { 1: [1, 0], 3: [1, 1], 4: [2, 0], 7: [2, 1], 9: [3, 0], 12: [2, 2], 13: [3, 1] };
  var NS = [1, 3, 4, 7, 9, 12, 13];
  // co-channel lattice in axial hex coordinates: generated by (i, j) and its 60° rotation (−j, i + j)
  function groupKey(q, r, i, j, N) { var m = ((q * (i + j) + r * j) % N + N) % N, n = ((r * i - q * j) % N + N) % N; return m + ',' + n; }
  function reuseD(R, N) { return R * Math.sqrt(3 * N); }
  function sir(N) { var q = Math.sqrt(3 * N); return 10 * Math.log10(Math.pow(q, 4) / 6); } // rough: 6 first-tier interferers, path-loss exponent 4
  if (typeof module !== 'undefined') module.exports = { groupKey: groupKey, reuseD: reuseD, sir: sir, IJ: IJ };

  var PAL = ['#f0a35e', '#9fc1e6', '#a8d5b5', '#e6b3cc', '#f5d76e', '#c3b6ea', '#8fd3cf', '#f2c2a8', '#d2df8f', '#b4cdf3', '#ecd0a8', '#c4e7b5', '#e8b9b9'];
  var PRE = { cells: { N: 7, R: 2, ch: 992 }, amps: { N: 7, R: 2, ch: 395 }, gsm: { N: 3, R: 2, ch: 992 }, gsm4: { N: 4, R: 2, ch: 992 } };

  D.register('reuse', function (root) {
    var st = JSON.parse(JSON.stringify(PRE.amps));
    var cv = D.canvas(1080, 610);
    var tabBox = h('div', { cls: 'w-card', style: 'padding:10px 14px;gap:4px' });
    function clr() { pre.set(''); }
    var nSeg = D.seg(NS.map(function (n) { return [String(n), String(n)]; }), String(st.N), function (k) { st.N = +k; clr(); draw(); });
    [].forEach.call(nSeg.el.children, function (b) { b.style.cssText = 'font-size:23px;padding:7px 15px'; });
    var rSl = D.slider('Cell radius R', 0.5, 10, 0.5, st.R, function (v) { return fmtN(v, 1) + ' km'; }, function (v) { st.R = v; clr(); draw(); });
    var cSl = D.slider('Channels for the operator', 50, 1000, 1, st.ch, function (v) { return String(v); }, function (v) { st.ch = v; clr(); draw(); });
    var pre = D.seg([['amps', 'AMPS 395, N = 7'], ['gsm', 'GSM 992, N = 3'], ['gsm4', 'GSM, N = 4']], 'amps', function (k) {
      st = JSON.parse(JSON.stringify(PRE[k])); nSeg.set(String(st.N)); rSl.set(st.R); cSl.set(st.ch); draw();
    });
    [].forEach.call(pre.el.children, function (b) { b.style.cssText = 'font-size:22px;padding:6px 12px'; });
    var form = h('div', { cls: 'w-f', style: 'font-size:22px;line-height:1.5' });
    var verdict = h('div', { cls: 'w-verdict', style: 'font-size:23px' });
    root.appendChild(h('div', { cls: 'w-row', style: 'gap:24px' }, [
      h('div', { cls: 'w-col', style: 'width:1080px;gap:12px' }, [cv.c, tabBox]),
      h('div', { cls: 'w-col', style: 'width:560px;gap:12px' }, [
        h('div', { cls: 'w-card', style: 'gap:8px;padding:12px 18px' }, [h('h4', { text: 'Cluster size N = i² + ij + j²' }), nSeg.el]),
        h('div', { cls: 'w-card', style: 'gap:8px;padding:12px 18px' }, [pre.el]),
        h('div', { cls: 'w-card', style: 'gap:0;padding:6px 18px 2px' }, [rSl.el, cSl.el]),
        h('div', { cls: 'w-card', style: 'padding:12px 18px' }, [form]),
        verdict])
    ]));

    function hexPath(g, x, y, s) { g.beginPath(); for (var k = 0; k < 6; k++) { var an = Math.PI / 180 * (60 * k - 30); var px = x + s * Math.cos(an), py = y + s * Math.sin(an); k ? g.lineTo(px, py) : g.moveTo(px, py); } g.closePath(); }

    function draw() {
      var N = st.N, ij = IJ[N], i = ij[0], j = ij[1], g = cv.g, w = cv.w, hh = cv.h;
      g.clearRect(0, 0, w, hh); g.fillStyle = C.panel; g.fillRect(0, 0, w, hh); g.strokeStyle = C.line; g.lineWidth = 1; g.strokeRect(0.5, 0.5, w - 1, hh - 1);
      var s = 37, cx = w / 2 - 40, cy = hh / 2 + 12;
      var P = function (q, r) { return [cx + s * Math.sqrt(3) * (q + r / 2), cy + s * 1.5 * r]; };
      // cells, numbered by distance from the centre so the centre cluster reads 1..N
      var cells = [];
      for (var r = -9; r <= 9; r++) for (var q = -16; q <= 16; q++) {
        var p = P(q, r); if (p[0] < -s || p[0] > w + s || p[1] < -s || p[1] > hh + s) continue;
        cells.push({ q: q, r: r, x: p[0], y: p[1], d: Math.hypot(p[0] - cx, p[1] - cy), key: groupKey(q, r, i, j, N) });
      }
      var order = cells.slice().sort(function (a, b) { return a.d - b.d || Math.atan2(a.y - cy, a.x - cx) - Math.atan2(b.y - cy, b.x - cx); });
      var lab = {}, next = 0, clus = []; order.forEach(function (c) { if (!(c.key in lab)) { lab[c.key] = next++; clus.push(c); } });
      var g1 = lab[groupKey(0, 0, i, j, N)];
      g.save(); g.beginPath(); g.rect(1, 1, w - 2, hh - 2); g.clip();
      cells.forEach(function (c) {
        var L = lab[c.key];
        hexPath(g, c.x, c.y, s * 0.98); g.fillStyle = PAL[L % PAL.length]; g.globalAlpha = L === g1 ? 1 : 0.55; g.fill(); g.globalAlpha = 1;
        g.strokeStyle = '#ffffff'; g.lineWidth = 2; g.stroke();
      });
      // cluster around the centre (cells numbered 1..N)
      clus.forEach(function (c) { hexPath(g, c.x, c.y, s * 0.98); g.strokeStyle = C.navy; g.lineWidth = 2.5; g.stroke(); });
      // co-channel set (group 1) outlined in red
      cells.forEach(function (c) { if (lab[c.key] === g1) { hexPath(g, c.x, c.y, s * 0.9); g.strokeStyle = C.red; g.lineWidth = 5; g.stroke(); } });
      // reuse distance D: centre → cell (i, j)
      var tp = P(i, j);
      var ux = tp[0] - cx, uy = tp[1] - cy, ul = Math.hypot(ux, uy); ux /= ul; uy /= ul;
      g.strokeStyle = C.navy; g.lineWidth = 4; g.beginPath(); g.moveTo(cx + 14 * ux, cy + 14 * uy); g.lineTo(tp[0] - 14 * ux, tp[1] - 14 * uy); g.stroke();
      // radius R on the centre cell
      var an = Math.PI / 180 * 150, rx = cx + s * 0.98 * Math.cos(an), ry = cy + s * 0.98 * Math.sin(an);
      g.strokeStyle = C.ink; g.lineWidth = 3; g.beginPath(); g.moveTo(cx + 14 * Math.cos(an), cy + 14 * Math.sin(an)); g.lineTo(rx, ry); g.stroke();
      g.font = '600 20px ' + SANS; g.textAlign = 'center'; g.textBaseline = 'middle';
      cells.forEach(function (c) { var L = lab[c.key]; g.fillStyle = L === g1 ? C.red : C.ink; g.fillText(String(L + 1), c.x, c.y); });
      g.font = '700 22px ' + SANS; g.fillStyle = C.ink; g.fillText('R', rx - 14, ry + 10);
      var tx = 'D = √' + (3 * N) + ' R = ' + fmtN(Math.sqrt(3 * N), 2) + ' R', tw = g.measureText(tx).width + 16, lx = tp[0] + s + 4, ly = tp[1];
      g.fillStyle = 'rgba(255,255,255,.95)'; g.fillRect(lx, ly - 16, tw, 32); g.strokeStyle = C.navy; g.lineWidth = 2; g.strokeRect(lx, ly - 16, tw, 32);
      g.fillStyle = C.navy; g.textAlign = 'left'; g.fillText(tx, lx + 8, ly + 1);
      g.restore();
      // legend
      g.fillStyle = 'rgba(251,250,247,.94)'; g.fillRect(12, 12, 470, 72); g.strokeStyle = C.line; g.strokeRect(12.5, 12.5, 470, 72);
      g.textAlign = 'left'; g.font = '600 21px ' + SANS; g.fillStyle = C.red; g.fillText('red outline: cells sharing group 1', 24, 34);
      g.fillStyle = C.navy; g.fillText('navy outline: one cluster of N = ' + N + (N === 1 ? ' cell' : ' cells'), 24, 64);
      // formula
      var Dkm = reuseD(st.R, N), per = st.ch / N;
      form.innerHTML = 'N = i² + ij + j² = ' + i + '² + ' + i + '·' + j + ' + ' + j + '² = <b>' + N + '</b>\n' +
        'D = R√(3N) = ' + fmtN(st.R, 1) + ' km × √' + (3 * N) + '\n  = <b>' + fmtN(Dkm, 2) + ' km</b>  (D/R = ' + fmtN(Math.sqrt(3 * N), 2) + ')\n' +
        'Per cell = ' + st.ch + ' / ' + N + ' = ' + fmtN(per, 1) + ' → <b>' + Math.floor(per + 1e-9) + '</b>';
      if (N <= 3) { verdict.className = 'w-verdict warn'; verdict.textContent = 'Many channels per cell, but same-group cells are close: strong interference (needs robust digital coding, like GSM).'; }
      else if (N >= 12) { verdict.className = 'w-verdict warn'; verdict.textContent = 'Same-group cells far apart: little interference, but few channels per cell.'; }
      else { verdict.className = 'w-verdict ok'; verdict.textContent = 'A middle choice: N = ' + N + ' balances channels per cell against co-channel interference.'; }
      // trade-off table (all valid N)
      var t = '<table class="w-tab" style="width:100%;font-size:22px"><tr><th class="rh">N</th>' + NS.map(function (n) { return '<th>' + n + '</th>'; }).join('') + '</tr>';
      t += '<tr><td class="rh">channels / cell</td>' + NS.map(function (n) { return '<td' + (n === N ? ' style="background:#fbe9da;font-weight:700"' : '') + '>' + Math.floor(st.ch / n + 1e-9) + '</td>'; }).join('') + '</tr>';
      t += '<tr><td class="rh">D (km)</td>' + NS.map(function (n) { return '<td' + (n === N ? ' style="background:#fbe9da;font-weight:700"' : '') + '>' + fmtN(reuseD(st.R, n), 1) + '</td>'; }).join('') + '</tr>';
      t += '<tr><td class="rh">S/I ≈ (D/R)⁴/6</td>' + NS.map(function (n) { return '<td' + (n === N ? ' style="background:#fbe9da;font-weight:700"' : '') + '>' + fmtN(sir(n), 1) + ' dB</td>'; }).join('') + '</tr></table>';
      tabBox.innerHTML = t + '<p class="w-note" style="font-size:22px">Last row: rough estimate (six nearest co-channel cells, path-loss exponent 4); larger N, less interference.</p>';
    }
    draw();
  });
})();
